<script setup>
import { router, useForm } from '@inertiajs/vue3';
import AppLayout from '@/Components/AppLayout.vue';
const props = defineProps({ member: Object, profile: Object, donations: Array, announcements: Array, directory: Array });
const profileForm = useForm({ status_saat_ini: props.profile?.status_saat_ini || 'Lainnya', instansi_kampus: props.profile?.instansi_kampus || '', pekerjaan: props.profile?.pekerjaan || '', domisili: props.profile?.domisili || '', media_sosial: props.profile?.media_sosial || '', show_contact: Boolean(props.profile?.show_contact) });
